const PREFIX_KEYS: [string, ProviderIconKey][] = [
  ["acpregistry", "acp"],
  ["acp", "acp"],
  ["claude", "claude"],
  ["codex", "codex"],
  ["openai", "codex"],
  ["cursor", "cursor"],
  ["opencode", "opencode"],
  ["grok", "grok"],
  ["muse", "muse"],
];

/**
 * 把 provider 实例 ID（如 `claudeAgent`、`acpRegistry_devin`、`codex_work`）
 * 归一到图标键；ACP registry agent 按后缀查专属图标，未知实例返回
 * undefined，由调用方用通用图标兜底。
 */
export function providerIconKey(instanceId: string): ProviderIconKey | undefined {
  const id = instanceId.trim();
  const acpAgent = /^acpregistry_(.+)$/i.exec(id)?.[1];
  if (acpAgent) {
    return (
      ACP_AGENT_KEYS[acpAgent.toLowerCase().replace(/_/g, "-")] ?? "acp"
    );
  }
  const name = /^[a-z]+/.exec(id.toLowerCase())?.[0] ?? "";
  if (name === "pi") return "pi";
  return PREFIX_KEYS.find(([prefix]) => name.startsWith(prefix))?.[1];
}
